def make_date_string(year: int, month: Optional[int], day: Optional[int]) -> str:
    """Format a check-in date at the precision supplied by the caller."""
    result = f'{year}'
    if month is not None:
        result += f'-{month:02}'
        if day is not None:
            result += f'-{day:02}'
    return result


class check_ins(delegate.page):
    path = r'/check-ins/OL(\d+)W'

    @authorized_for('/usergroup/admin')
    def GET(self, work_id):
        return render_template('check_ins/test_form')

    @authorized_for('/usergroup/admin')
    def POST(self, work_id):
        """Creates a check-in for the given work.

        Additional data is expected to be sent as JSON in the body, and will
        have the following keys:
        edition_olid : str,
        event_type : str,
        year : integer,
        month : integer [optional],
        day : integer [optional]
        """
        data = json.loads(web.data())
        valid_request = self.is_valid(data)
        user = get_current_user()
        username = user['key'].split('/')[-1]

        if valid_request and username:
            edition_id = extract_numeric_id_from_olid(data['edition_olid'])
            date_str = make_date_string(
                data['year'], data.get('month', None), data.get('day', None)
            )
            event_type = BookshelvesEvents.EVENT_TYPES[data['event_type']]
            BookshelvesEvents.create_event(
                username, work_id, edition_id, date_str, event_type=event_type
            )
        else:
            return web.badrequest(message="Invalid request")
        return delegate.RawText(json.dumps({'status': 'ok'}))

    def is_valid(self, data: dict) -> bool:
        """Validates POSTed check-in data."""
        if not all(key in data for key in ('edition_olid', 'year', 'event_type')):
            return False
        if data['event_type'] not in BookshelvesEvents.EVENT_TYPES:
            return False
        return True

    # Preserve the existing instance API while sharing the formatter with updates.
    make_date_string = staticmethod(make_date_string)


class patron_check_ins(delegate.page):
    path = r'/people/([^/]+)/check-ins'

    def is_valid(self, data) -> bool:
        """Require an event id and at least one value to update."""
        return isinstance(data, dict) and 'id' in data and (
            'year' in data or 'data' in data
        )

    def POST(self, username):
        user = get_current_user()
        if not user:
            return web.unauthorized(message='Requires log-in.')
        if user['key'].split('/')[-1] != username:
            return web.forbidden(message='Cannot update another patron\'s check-in.')

        try:
            request = json.loads(web.data())
        except (TypeError, ValueError):
            return web.badrequest(message='Invalid request')
        if not self.is_valid(request):
            return web.badrequest(message='Invalid request')

        event_id = request['id']
        if not any(
            event['id'] == event_id
            for event in BookshelvesEvents.select_all_by_username(username)
        ):
            return web.notfound(message='Check-in not found')

        if 'year' in request:
            event_date = make_date_string(
                request['year'], request.get('month'), request.get('day')
            )
            BookshelvesEvents.update_event_date(event_id, event_date)
        if 'data' in request:
            BookshelvesEvents.update_event_data(event_id, json.dumps(request['data']))
        return delegate.RawText(json.dumps({'status': 'ok'}))


