class BookshelvesEvents:

    TABLENAME = 'bookshelves_events'
    EVENT_TYPES = {
        'start': 1,
        'update': 2,
        'finish': 3,
    }

    # Create methods:
    @classmethod
    def create_event(
        cls, username, work_id, edition_id, event_date, event_type=EVENT_TYPES['start']
    ):
        oldb = db.get_db()

        return oldb.insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            edition_id=edition_id,
            event_type=event_type,
            event_date=event_date,
        )

    # Read methods:
    @classmethod
    def select_all_by_username(cls, username):
        # TODO: how should these be ordered?  edition_id and event_date?
        oldb = db.get_db()

        where_clause = 'username=$username'
        where_vars = {'username': username}
        return list(oldb.select(cls.TABLENAME, where=where_clause, vars=where_vars))

    # Update methods:
    @classmethod
    def update_event_date(cls, pid, event_date):
        oldb = db.get_db()

        where_clause = 'id=$id'
        where_vars = {'id': pid}
        update_time = datetime.utcnow()

        return oldb.update(
            cls.TABLENAME,
            where=where_clause,
            vars=where_vars,
            updated=update_time,
            event_date=event_date,
        )

    @classmethod
    def update_event_data(cls, pid, data):
        oldb = db.get_db()

        where_clause = 'id=$id'
        where_vars = {'id': pid}
        update_time = datetime.utcnow()

        return oldb.update(
            cls.TABLENAME,
            where=where_clause,
            vars=where_vars,
            updated=update_time,
            data=data,
        )

